import{_ as r,o as d,c as o,ag as a}from"./chunks/framework.DoUXNnsN.js";const c=JSON.parse('{"title":"PCB制造流程","description":"","frontmatter":{"title":"PCB制造流程","aliases":["PCB","印制电路板","线路板","PCB制程","PWB"],"tags":["制造业务","地图","工艺"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Printed_circuit_board_manufacturing","https://en.wikipedia.org/wiki/Printed_circuit_board","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":2},"headers":[],"relativePath":"80-电子制造业务/地图/PCB制造流程.md","filePath":"80-电子制造业务/地图/PCB制造流程.md"}'),i={name:"80-电子制造业务/地图/PCB制造流程.md"};function e(n,t,l,s,h,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<blockquote class="callout-warn"><p>⚠ 待核对：本篇的工序顺序和各步骤的做法已对照维基百科的&quot;Printed circuit board manufacturing&quot;词条；其中&quot;开料&quot;一步、各种表面处理的优缺点、不良现象的成因、以及 IPC-A-600 这个标准名称，来自通用知识，没有逐条联网核实。各工厂的具体流程和参数不同，请以公司工艺文件为准。</p></blockquote><blockquote><p>本篇是&quot;电子制造业务&quot;的<strong>地图</strong>之一。读完你应该能：说出一块多层 PCB 从覆铜板到成品要经过哪些工序，每一步为什么做；认出常见的表面处理和不良现象；知道 MES、QMS 在 PCB 厂里分别记录什么。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>PCB（Printed Circuit Board，印制电路板）是承载电子元器件并用铜线路把它们连接起来的板。PCB 制造流程，就是把一张<strong>覆铜板</strong>加工成有线路、有孔、有阻焊层和标识的<strong>裸板</strong>（还没有贴元件的板）。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>知道电路是由元器件和导线组成的即可。</li><li>本篇讲的是&quot;裸板怎么做出来&quot;；元件怎么贴上去，见 <a href="/Encyclopedia/80-电子制造业务/地图/SMT与电子组装流程">SMT与电子组装流程</a>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>电子元件之间需要导线连接。早期靠手工飞线，慢且容易错。PCB 把整套连接&quot;印&quot;在一块板上，可以批量、一致地生产，并且能做到很高的密度。</p><p>对做信息化的人来说，PCB 厂是&quot;流程长、工序多、每步都有良率损失&quot;的典型场景：一块多层板要经过十几道工序，任何一步出问题（线路开路、孔里没铜、阻焊偏位）都会变成不良品。所以追溯和质量管理（<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a>）在这里特别重要。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="板子的结构" tabindex="-1">板子的结构 <a class="header-anchor" href="#板子的结构" aria-label="Permalink to &quot;板子的结构&quot;">​</a></h3><ul><li><strong>基材</strong>：最常见的绝缘基材是 <strong>FR-4</strong>，它是浸了环氧树脂的玻璃纤维布。</li><li><strong>铜箔</strong>：覆在基材表面，经过加工变成线路。</li><li><strong>半固化片（Prepreg）</strong>：多层板压合时夹在层与层之间的粘合材料。</li><li><strong>孔和过孔（Via）</strong>：过孔是内壁镀了金属的钻孔，用来让不同层的线路连通。</li><li><strong>阻焊（Solder mask）</strong>：盖在线路上的保护层，防止焊接时短路；只有要焊接的焊盘会露出来。外层需要阻焊，内层的铜被基材保护。</li><li><strong>字符（Legend / 丝印）</strong>：印在板上的文字和标记，如元件编号、板名。</li></ul><p><strong>多层板怎么叠</strong>：以四层板为例，先做一块两面都有铜的&quot;芯板&quot;，在它的两侧各放一层半固化片和铜箔，压在一起，就得到四层铜。</p><h3 id="流程总览" tabindex="-1">流程总览 <a class="header-anchor" href="#流程总览" aria-label="Permalink to &quot;流程总览&quot;">​</a></h3><p>下面是一块多层刚性板的主要工序。顺序对照了维基百科对 PCB 制造的描述，名称是行业里的常用叫法。</p><table tabindex="0"><thead><tr><th>序号</th><th>工序</th><th>做什么</th><th>为什么</th></tr></thead><tbody><tr><td>1</td><td>开料</td><td>把大张覆铜板切成生产用的尺寸</td><td>便于后续加工</td></tr><tr><td>2</td><td>内层图形</td><td>在铜面涂感光膜，通过底片曝光、显影，留下线路形状的保护层</td><td>决定哪些铜要保留</td></tr><tr><td>3</td><td>内层蚀刻</td><td>用药水蚀刻掉没有保护的铜，剩下线路</td><td>形成内层线路</td></tr><tr><td>4</td><td>内层检查</td><td>用自动光学检查（AOI）对照设计数据检查线路</td><td>压合之后就无法返修，所以要在压合前查</td></tr><tr><td>5</td><td>层压</td><td>把各层和半固化片叠起来，加热加压压成一整块</td><td>形成多层结构</td></tr><tr><td>6</td><td>钻孔</td><td>用钻头钻出通孔；很小的微孔用激光钻</td><td>为层间连通和插件元件开孔</td></tr><tr><td>7</td><td>去钻污</td><td>去除钻孔后残留在孔壁的树脂</td><td>否则孔壁镀不牢，会开路</td></tr><tr><td>8</td><td>孔金属化</td><td>先在孔壁化学沉积一层薄铜，再电镀加厚</td><td>让孔壁导电，连通各层</td></tr><tr><td>9</td><td>外层图形</td><td>在外层铜面形成线路图形</td><td>形成外层线路</td></tr><tr><td>10</td><td>阻焊</td><td>涂感光阻焊油墨，曝光显影，露出焊盘</td><td>保护线路，防短路</td></tr><tr><td>11</td><td>字符</td><td>印上文字标识</td><td>方便识别和装配</td></tr><tr><td>12</td><td>表面处理</td><td>给露出的焊盘做保护层</td><td>防止铜氧化，保证后续可焊</td></tr><tr><td>13</td><td>电测</td><td>测试每个网络有没有短路和开路</td><td>出货前的主要电气检查</td></tr><tr><td>14</td><td>成型</td><td>铣切或分割出板的外形，把拼板分开</td><td>得到单块成品</td></tr><tr><td>15</td><td>终检包装</td><td>外观检查（含 AOI，必要时 X-ray），包装出货</td><td>最后一道关</td></tr></tbody></table><h3 id="几个关键工序的细节" tabindex="-1">几个关键工序的细节 <a class="header-anchor" href="#几个关键工序的细节" aria-label="Permalink to &quot;几个关键工序的细节&quot;">​</a></h3><p><strong>图形转移与蚀刻</strong>：用感光膜保护要留下的线路，其余的铜被药水腐蚀掉。蚀刻有&quot;侧蚀&quot;的风险：药水会从侧面腐蚀线路，使线变细甚至断开。线路越细，对控制越严。</p><p><strong>钻孔与去钻污</strong>：机械钻孔用硬质合金钻头，钻孔数据来自一份钻孔文件。多层板钻孔后孔壁会有树脂&quot;钻污&quot;，需要用化学药水或等离子去除，否则会影响孔金属化的可靠性。很小的微孔（小于约 76 微米）用激光钻。</p><p><strong>盲孔与埋孔</strong>：不是所有过孔都贯穿整块板。<strong>盲孔</strong>从外层通到内层，<strong>埋孔</strong>完全在内层之间。它们靠控制钻孔深度、激光钻孔或者在层压前先钻内层来做出来。</p><p><strong>减成法与半加成法</strong>：把不需要的铜腐蚀掉，叫&quot;减成法&quot;，是最传统的做法。&quot;半加成法&quot;是先有一层极薄的铜底，只在需要线路的地方镀上铜，最后把底铜微蚀掉。后者更适合很细的线路。</p><p><strong>阻焊与字符</strong>：常用的是液态感光阻焊（LPI），曝光显影后只留下需要覆盖的区域；字符可以丝网印刷，也可以用感光工艺或喷墨，其中喷墨能印可变的内容，比如序列号。</p><h3 id="表面处理-给焊盘穿-保护衣" tabindex="-1">表面处理：给焊盘穿&quot;保护衣&quot; <a class="header-anchor" href="#表面处理-给焊盘穿-保护衣" aria-label="Permalink to &quot;表面处理：给焊盘穿&quot;保护衣&quot;&quot;">​</a></h3><p>裸露的铜焊盘很容易氧化，氧化后就焊不上。所以要在上面做一层保护。常见的几种：</p><table tabindex="0"><thead><tr><th>名称</th><th>简称</th><th>特点（通用说法，选型以设计和工艺要求为准）</th></tr></thead><tbody><tr><td>有机保焊膜</td><td>OSP</td><td>在铜面形成一层有机薄膜，成本低、平整；存放时间有限</td></tr><tr><td>热风整平</td><td>HASL</td><td>把板子浸入熔融焊锡再用热风吹平；表面不够平整，不太适合很细间距的元件</td></tr><tr><td>化学镍金</td><td>ENIG</td><td>在铜上镀镍再镀一层薄金；表面平整，适合细间距，也常用于金手指等需要耐磨的接触位置</td></tr><tr><td>化学镍钯金</td><td>ENEPIG</td><td>在镍和金之间多一层钯</td></tr><tr><td>沉银</td><td>ImAg</td><td>在铜上沉积一层薄银；银在含卤素的环境里可能长出导电的&quot;枝晶&quot;</td></tr><tr><td>沉锡</td><td>ImSn</td><td>在铜上沉积一层薄锡；锡可能长出&quot;锡须&quot;，还会与铜形成金属间化合物</td></tr></tbody></table><p><strong>怎么选</strong>：这是设计和工艺团队的事，要平衡成本、平整度、存放期、可靠性。你只需要知道：<strong>表面处理不同，后面 SMT 焊接的工艺窗口和存放要求也会不同</strong>。</p><h3 id="电测-用什么方法" tabindex="-1">电测：用什么方法 <a class="header-anchor" href="#电测-用什么方法" aria-label="Permalink to &quot;电测：用什么方法&quot;">​</a></h3><p>裸板电测检查的是&quot;该通的通、该断的断&quot;，即查<strong>短路</strong>和<strong>开路</strong>。常见两种方法：</p><ul><li><strong>针床（固定治具）</strong>：做一套带很多探针的治具，一压就测完整块板，速度快，适合大批量；但治具成本高，要为每种板子做一套。</li><li><strong>飞针</strong>：用几根可以在平面上移动的探针逐点测试，不需要治具，适合小批量和打样，但速度慢。</li></ul><h2 id="逐步例子-一块-4-层板的旅程与追溯" tabindex="-1">逐步例子：一块 4 层板的旅程与追溯 <a class="header-anchor" href="#逐步例子-一块-4-层板的旅程与追溯" aria-label="Permalink to &quot;逐步例子：一块 4 层板的旅程与追溯&quot;">​</a></h2><p>一块板的信息怎么在流程中被记录，是 MES 和 QMS 关心的重点。假设现在做一批 4 层板：</p><ol><li><strong>开料</strong>后，一张大板（Panel，里面会拼多块单板）得到一个<strong>批次号</strong>和<strong>拼板编号</strong>，比如 <code>LOT-0042-P07</code>。</li><li>内层图形、蚀刻、AOI：每一步，操作员或设备扫描拼板编号，系统记录<strong>工序、设备、时间、参数</strong>（比如蚀刻线的速度、药水浓度）和检查结果。<strong>发现内层缺陷的拼板被拦下</strong>，不进入层压。</li><li><strong>层压</strong>之后，常在板边打上二维码或条码，之后每道工序都靠它识别这块拼板。</li><li><strong>钻孔</strong>时记录用的钻头和孔数据；<strong>孔金属化</strong>记录槽液参数。</li><li><strong>电测</strong>时，每块单板的测试结果（通过、短路、开路）连同它在拼板中的位置，被写入系统。</li><li><strong>成型</strong>后，拼板被分成单板。有的厂会在这一步给<strong>每块单板</strong>打上单板码，之后追溯就细到&quot;这块板&quot;而不是&quot;这一拼板&quot;。</li><li>到 <strong>终检</strong>，不良板被分类（开路、短路、阻焊不良等）并记录<strong>不良代码</strong>。</li></ol><p>这样，客户万一投诉某块板有问题，就可以从板码一路查到：哪个批次、哪台设备、什么参数、哪个操作员、哪次检测结果。这就是&quot;追溯&quot;（Traceability）。具体系统怎么实现，见 <a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>。</p><h2 id="常见不良与排查" tabindex="-1">常见不良与排查 <a class="header-anchor" href="#常见不良与排查" aria-label="Permalink to &quot;常见不良与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>不良</th><th>通俗解释</th><th>可能原因（通用经验）</th></tr></thead><tbody><tr><td>开路</td><td>本该连通的线断了</td><td>线路蚀刻过度（侧蚀使线变细）、孔壁镀铜不良、划伤</td></tr><tr><td>短路</td><td>本不该相连的线连上了</td><td>蚀刻不净、铜渣残留、阻焊或线路设计间距过小</td></tr><tr><td>孔内无铜 / 孔破</td><td>孔壁没镀上铜或镀层破裂</td><td>去钻污不彻底、化学沉铜不良、钻孔质量差</td></tr><tr><td>阻焊偏位 / 上焊盘</td><td>阻焊油墨盖到了焊盘上</td><td>曝光对位偏差</td></tr><tr><td>分层</td><td>板内层与层之间分离</td><td>层压参数不当、板材受潮、受热冲击</td></tr><tr><td>板翘</td><td>板子不平整</td><td>材料和层结构不对称、应力、受热</td></tr><tr><td>焊盘氧化 / 可焊性差</td><td>焊盘变色、焊不上</td><td>表面处理不良或存放过久、受潮</td></tr><tr><td>字符不清 / 偏移</td><td>文字模糊或位置不对</td><td>印刷或曝光参数</td></tr></tbody></table><p>以上&quot;可能原因&quot;是行业通用经验，用于帮助理解；具体分析要靠工艺工程师的失效分析。</p><h2 id="动手实验-拆解一块旧板-亲眼认识-pcb" tabindex="-1">动手实验：拆解一块旧板，亲眼认识 PCB <a class="header-anchor" href="#动手实验-拆解一块旧板-亲眼认识-pcb" aria-label="Permalink to &quot;动手实验：拆解一块旧板，亲眼认识 PCB&quot;">​</a></h2><p>你需要一块<strong>废弃</strong>的 PCB（旧路由器、旧遥控器、旧充电器里的板都可以）、一个放大镜（或手机的微距拍照）。<strong>不要用火烧、不要拆带电池或电容仍有电的设备。</strong></p><ol><li>看<strong>颜色</strong>：板子主要是什么颜色？这是阻焊的颜色（绿色最常见，但也有蓝、黑、红、白等），它不影响电气性能。</li><li>看<strong>字符</strong>：找找板上白色的文字，认出元件编号（如 R1、C3、U2）。这些就是丝印字符。</li><li>看<strong>焊盘</strong>：露出来的焊盘是什么样子？金黄色一般说明做了化学镍金；银灰色发亮、表面稍有起伏的，常是热风整平；暗铜色、表面平整的，可能是 OSP。（只凭肉眼判断不一定准，当作观察练习。）</li><li>找<strong>过孔</strong>：在板的两面找小圆点，并对着光看，哪些孔能透光（通孔），哪些不透光（可能是盲孔、被阻焊盖住的过孔）。</li><li>看<strong>板边</strong>：板子是不是从一整块拼板上分下来的？边缘有没有&quot;邮票孔&quot;或锯齿状的断点，这就是分板的痕迹。</li><li>把你观察到的整理成一张表：颜色、表面处理判断、过孔数量、板边特征。想一想：如果是你来设计追溯，你会把板码打在哪里？</li></ol><h2 id="常见坑与误区" tabindex="-1">常见坑与误区 <a class="header-anchor" href="#常见坑与误区" aria-label="Permalink to &quot;常见坑与误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>事实</th></tr></thead><tbody><tr><td>把 PCB 和 PCBA 混为一谈</td><td>PCB 是裸板，PCBA（PCB Assembly）是贴好元件的板，后者是 SMT 的产物</td></tr><tr><td>以为所有过孔都贯穿整块板</td><td>有通孔、盲孔、埋孔，制造难度和成本不同</td></tr><tr><td>以为阻焊颜色影响性能</td><td>颜色主要是外观，电气性能由材料和设计决定</td></tr><tr><td>以为 PCB 工序可以随便调顺序</td><td>比如内层必须在压合前检查，压合后内层缺陷就无法返修</td></tr><tr><td>以为表面处理只是&quot;好看&quot;</td><td>它直接决定后续焊接的可焊性和存放期</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>为什么内层线路要在<strong>层压之前</strong>做 AOI 检查？ <strong>答</strong>：层压之后，内层被封在板里，缺陷无法返修，所以必须在压合前把内层缺陷查出来。</li><li>孔金属化为什么要先&quot;去钻污&quot;？ <strong>答</strong>：钻孔后孔壁上有残留的树脂钻污，会让后面沉铜、镀铜附着不牢，容易孔内开路，所以要先去除。</li><li>四层板的基本做法是什么？ <strong>答</strong>：先做一块两面有铜的芯板，在两侧各放半固化片和铜箔，压合成四层铜，再钻孔、孔金属化、做外层和后续工序。</li><li>针床测试和飞针测试，哪个更适合小批量打样？为什么？ <strong>答</strong>：飞针。它不需要做专用治具，换板不用换治具；针床要为每种板做治具，成本高，适合大批量。</li><li>某批板子在 SMT 贴片时出现大量&quot;焊盘焊不上&quot;，首先怀疑 PCB 制造的哪个环节？ <strong>答</strong>：表面处理（焊盘氧化、可焊性差），也要检查板子的存放时间和环境。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PCB 是承载并连通元件的板，制造流程是把覆铜板做成有线路、孔、阻焊、字符的裸板。</li><li>主要工序：开料、内层图形与蚀刻、内层检查、层压、钻孔、去钻污、孔金属化、外层图形、阻焊、字符、表面处理、电测、成型、终检。</li><li>表面处理有 OSP、HASL、ENIG、ENEPIG、沉银、沉锡等，各有取舍。</li><li>电测查短路和开路，针床适合大批量，飞针适合小批量。</li><li>每一步都要扫码记录批次、设备、参数和检查结果，这是追溯的基础。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/80-电子制造业务/地图/SMT与电子组装流程">SMT与电子组装流程</a>、<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a>、<a href="/Encyclopedia/80-电子制造业务/地图/ISA-95">ISA-95</a>、<a href="/Encyclopedia/80-电子制造业务/地图/电子制造信息系统全景图">电子制造信息系统全景图</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>维基百科 PCB 制造词条：<a href="https://en.wikipedia.org/wiki/Printed_circuit_board_manufacturing" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Printed_circuit_board_manufacturing</a></li><li>维基百科 PCB 词条：<a href="https://en.wikipedia.org/wiki/Printed_circuit_board" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Printed_circuit_board</a></li></ul>',49)])])}const q=r(i,[["render",e]]);export{c as __pageData,q as default};
